/**
 * KONSENSOMAT — geheime Abstimmung für kleine Gruppen.
 *
 * Alle stimmen blind ab. Erst wenn alle Stimmen vorliegen, zeigt die Seite das
 * Ergebnis. Der Administrator legt vorher fest, wie ausgewertet wird:
 *
 *   einstimmig      alle müssen dasselbe sagen (der ursprüngliche Konsensomat)
 *   einfach         mehr als die Hälfte der gültigen Stimmen
 *   zweidrittel     mindestens zwei Drittel der gültigen Stimmen
 *
 * Antwortform: entweder vorgegebene Optionen (Ja/Nein, Kandidatennamen, …) oder
 * freie Eingabe. Mehrheiten gibt es nur mit Optionen, sonst scheitert die
 * Auszählung an Tippfehlern („Müller" vs. „mueller").
 *
 * Zur Geheimhaltung wird bewusst NICHT gespeichert:
 *   1. keine Verbindung zwischen Person und Stimme,
 *   2. bei freier Eingabe kein Klartext, solange die Runde läuft,
 *   3. nach dem Abschluss fliegt auch der Vergleichs-Hash wieder raus.
 * Restrisiko, ehrlich benannt: wer die Datenbank live mitliest, sieht bei
 * Optionen den Zwischenstand mitwachsen. Gegen den Betreiber selbst schützt
 * nur ein Verfahren mit Schlüsseln auf den Geräten der Teilnehmer.
 *
 * Jede Abstimmung ist ein eigenes Durable Object. Dadurch werden Stimmen
 * nacheinander verarbeitet und können sich nicht gegenseitig überschreiben.
 */

import qrcode from 'qrcode-generator';

const ENC = new TextEncoder();

/** QR als SVG-Pfad. Kein Bild, keine externe Anfrage, druckt sauber. */
function qrSvg(text, groesse = 150) {
  const q = qrcode(0, 'M');
  q.addData(text);
  q.make();
  const n = q.getModuleCount();
  let d = '';
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      if (q.isDark(r, c)) d += `M${c},${r}h1v1h-1z`;
    }
  }
  const rand = 2;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${groesse}" height="${groesse}"
    viewBox="${-rand} ${-rand} ${n + rand * 2} ${n + rand * 2}" shape-rendering="crispEdges">
    <rect x="${-rand}" y="${-rand}" width="${n + rand * 2}" height="${n + rand * 2}" fill="#fff"/>
    <path d="${d}" fill="#111"/></svg>`;
}

const hex = (buf) =>
  Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, '0')).join('');

const zufall = (bytes) => hex(crypto.getRandomValues(new Uint8Array(bytes)));

// Screenshot der Anlege-Seite mit den Einstellungen der Probe-Abstimmung.
// Eingebettet als data-URI, weil jeder eigene Pfad ausserhalb /a/* und /info
// hinter der Cloudflare-Access-Wand laege.
const DEMO_ADMIN_BILD = 'data:image/png;base64,';

// Der Don selbst, fuer den Gruss nach dreimal Ja in der Probe-Abstimmung.
const DON_FOTO = 'data:image/jpeg;base64,';

// Alphabet ohne Verwechslungspaare: von O/0, I/1 und B/8 steht höchstens ein
// Zeichen drin (0 und 8 ja, O, B, I und 1 nicht). So sind es genau 32 Zeichen,
// also 5 Bit je Stelle ohne Rest beim Würfeln: ein achtstelliger Code hat
// 2^40, gut eine Billion Möglichkeiten.
const ALPHABET = 'ACDEFGHJKLMNPQRSTUVWXYZ023456789';
function lesbarerCode(stellen = 8) {
  const b = crypto.getRandomValues(new Uint8Array(stellen));
  let raus = '';
  for (let i = 0; i < stellen; i++) {
    if (i === 4) raus += '-';
    raus += ALPHABET[b[i] % ALPHABET.length];
  }
  return raus;
}

/** Codes vergleichbar machen: Bindestriche und Leerzeichen sind egal, und wer
 *  O statt 0 oder B statt 8 abtippt, wird geheilt (beide stehen nie im Code). */
const codeNormal = (c) =>
  String(c || '').toUpperCase().replace(/[^A-Z0-9]/g, '').replace(/O/g, '0').replace(/B/g, '8');

const escape = (s) =>
  String(s).replace(/[&<>"']/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

/** Freitext vereinheitlichen, damit „ Ja." und „ja" als dasselbe zählen. */
const normalisieren = (text) =>
  String(text).trim().toLowerCase().replace(/\s+/g, ' ').replace(/[.!?,;:]+$/, '');

/** Gesalzener Hash. Der Salt gilt nur für diese eine Runde. */
async function hashen(salt, text) {
  return hex(await crypto.subtle.digest('SHA-256', ENC.encode(salt + '␀' + text)));
}

const MAX_FEHLVERSUCHE = 12;
// Frage der Probe-Abstimmung. Sie steht hier, weil sowohl die Runde als auch
// die Strichliste sie brauchen.
const DEMO_FRAGE = 'Willst du den Quellcode?';
// Nach dieser Frist löscht sich eine Abstimmung von selbst (Datensparsamkeit).
const AUFBEWAHRUNG_TAGE = 60;

const MODI = {
  einstimmig: { name: 'Einstimmig', kurz: 'alle müssen dasselbe sagen' },
  einfach: { name: 'Einfache Mehrheit', kurz: 'mehr als die Hälfte der gültigen Stimmen' },
  zweidrittel: { name: 'Zweidrittelmehrheit', kurz: 'mindestens zwei Drittel der gültigen Stimmen' },
};

/* ------------------------------------------------------------------ */
/* Durable Object: eine Abstimmung                                      */
/* ------------------------------------------------------------------ */

export class Abstimmung {
  constructor(state) {
    this.state = state;
  }

  async fetch(request) {
    const aktion = new URL(request.url).pathname.slice(1);
    const eingabe = request.method === 'POST' ? await request.json() : {};

    return await this.state.blockConcurrencyWhile(async () => {
      const s = await this.state.storage.get('sitzung');
      let ergebnis;
      switch (aktion) {
        case 'anlegen':
          ergebnis = await this.anlegen(eingabe);
          break;
        case 'lesen':
          ergebnis = this.oeffentlich(s, eingabe.waehler);
          break;
        case 'stimmen':
          ergebnis = await this.stimmen(s, eingabe);
          break;
        case 'entsperren':
          ergebnis = await this.entsperren(s, eingabe);
          break;
        case 'neustart':
          // Nur die Demo: eine fertige Runde beim naechsten Seitenaufruf leeren,
          // damit jeder Test bei 0 von 3 beginnt.
          if (s && s.demo && s.fertig) {
            Object.assign(s, this.leererStand(s.optionen), { salt: zufall(16) });
            await this.state.storage.put('sitzung', s);
          }
          ergebnis = { ok: true };
          break;
        case 'leeren':
          // Strichliste zurücksetzen. Nimmt die alte gemeinsame Demo-Runde
          // gleich mit, sonst würden ihre Zahlen beim nächsten Strich wieder
          // als Startwert übernommen.
          await this.state.storage.deleteAll();
          ergebnis = { ok: true };
          break;
        case 'strich':
          ergebnis = { gesamt: await this.strichliste(s, eingabe) };
          break;
        case 'stand':
          ergebnis = { frage: DEMO_FRAGE, gesamt: await this.strichliste(s) };
          break;
        case 'karten':
          ergebnis =
            !s || eingabe.admin !== s.admin
              ? { fehler: 'nicht erlaubt' }
              : {
                  frage: s.frage,
                  ziel: s.ziel,
                  codes: s.codes ? s.codes.map((c) => ({ code: c.klar, benutzt: c.benutzt })) : null,
                };
          break;
        case 'loeschen':
          if (!s || eingabe.admin !== s.admin) ergebnis = { fehler: 'nicht erlaubt' };
          else {
            await this.state.storage.deleteAll();
            ergebnis = { ok: true };
          }
          break;
        default:
          ergebnis = { fehler: 'unbekannt' };
      }
      return new Response(JSON.stringify(ergebnis), {
        headers: { 'Content-Type': 'application/json' },
      });
    });
  }

  async anlegen({ frage, ziel, modus, optionen, enthaltung, codes, demo }) {
    const admin = zufall(16);
    const art = MODI[modus] ? modus : 'einstimmig';

    // Optionen säubern; Mehrheitsmodi verlangen mindestens zwei davon.
    let opt = (optionen || [])
      .map((o) => String(o).trim())
      .filter(Boolean)
      .slice(0, 12)
      .map((text) => ({ text, zaehlt: true }));
    if (opt.length < 2) opt = null;
    if (!opt && art !== 'einstimmig') {
      return { fehler: 'Für Mehrheiten braucht es vorgegebene Optionen.' };
    }
    if (!String(frage || '').trim()) return { fehler: 'Ohne Frage keine Abstimmung.' };
    if (opt && enthaltung) opt.push({ text: 'Enthaltung', zaehlt: false });

    const sitzung = {
      frage: String(frage || '').slice(0, 200),
      ziel: Math.min(Math.max(parseInt(ziel, 10) || 3, 2), 50),
      modus: art,
      optionen: opt,
      salt: zufall(16),
      admin,
      erstellt: new Date().toISOString(),
      codes: null,
      // Probe-Abstimmung: eine eigene Runde je Geraet, die sich nach jeder
      // vollen Runde selbst zuruecksetzt. Die anonyme Strichliste ueber alle
      // Runden liegt getrennt davon im Zaehl-Objekt 'demo'.
      demo: !!demo,
      ...this.leererStand(opt),
    };

    let klartextCodes = null;
    if (codes) {
      klartextCodes = Array.from({ length: sitzung.ziel }, () => lesbarerCode());
      sitzung.codes = [];
      for (const c of klartextCodes) {
        // Der Klartext bleibt hier liegen, damit der Administrator die Wahlkarten
        // nachdrucken kann. Ein Code sagt nichts darüber aus, WIE jemand
        // gestimmt hat, er belegt nur die Berechtigung.
        sitzung.codes.push({ h: await hashen(sitzung.salt, codeNormal(c)), klar: c, benutzt: false });
      }
    }
    await this.state.storage.put('sitzung', sitzung);
    await this.state.storage.setAlarm(Date.now() + AUFBEWAHRUNG_TAGE * 86400000);
    return { admin, codes: klartextCodes };
  }

  leererStand(opt) {
    return {
      zaehler: opt ? opt.map(() => 0) : null, // Stimmen je Option, ohne Personenbezug
      ersterHash: null, // nur im Freitext-Fall, fliegt beim Abschluss raus
      einig: true,
      abgegeben: 0,
      waehler: [],
      quittungen: [], // Belege der Wähler, sortiert, ohne Bezug zur Stimme
      fehlversuche: 0,
      fertig: false,
      ergebnis: null,
    };
  }

  /**
   * Anonyme Strichliste der Probe-Abstimmung. Sie liegt in einem eigenen
   * Objekt neben allen Runden, damit weder ein Neustart noch die Aufbewahrungs-
   * frist sie mitnimmt. Ohne Eingabe wird nur gelesen.
   */
  async strichliste(s, { text, runde } = {}) {
    let liste = await this.state.storage.get('strichliste');
    // Einmalige Übernahme der Zahlen aus der früheren gemeinsamen Demo-Runde.
    if (!liste) liste = s && s.gesamt ? { ...s.gesamt } : { runden: 0 };
    if (text) liste[text] = (liste[text] || 0) + 1;
    if (runde) liste.runden = (liste.runden || 0) + 1;
    await this.state.storage.put('strichliste', liste);
    return liste;
  }

  /** Räumt die Abstimmung nach Ablauf der Frist selbst weg. */
  async alarm() {
    // Die Strichliste zählt über Jahre und überlebt das Aufräumen.
    const liste = await this.state.storage.get('strichliste');
    await this.state.storage.deleteAll();
    if (liste) await this.state.storage.put('strichliste', liste);
  }

  /** Was die Seite sehen darf. Salt, Hash, Admin-Token und Codes bleiben drin. */
  oeffentlich(s, waehler) {
    if (!s) return { fehlt: true };
    return {
      frage: s.frage,
      ziel: s.ziel,
      modus: s.modus,
      optionen: s.optionen ? s.optionen.map((o) => o.text) : null,
      abgegeben: s.abgegeben,
      fertig: s.fertig,
      ergebnis: s.ergebnis,
      mitCodes: !!s.codes,
      gestartet: s.abgegeben > 0,
      schonGestimmt: s.demo ? false : waehler ? s.waehler.includes(waehler) : false,
      demo: !!s.demo,
      quittungen: s.fertig ? s.quittungen : null,
      gesperrt: (s.fehlversuche || 0) >= MAX_FEHLVERSUCHE,
      erstellt: s.erstellt,
    };
  }

  async stimmen(s, { antwort, waehler, code }) {
    if (!s) return { fehler: 'Diese Abstimmung gibt es nicht mehr.' };
    if (s.fertig && s.demo) {
      // Demo: die naechste Stimme eroeffnet automatisch eine neue Runde.
      Object.assign(s, this.leererStand(s.optionen), { salt: zufall(16) });
    }
    if (s.fertig) return { fehler: 'Diese Runde ist bereits abgeschlossen.' };
    // Demo: mehrfaches Abstimmen ist erlaubt, auch vom selben Geraet — zum
    // Ausprobieren braucht niemand drei Browser.
    if (!s.demo && s.waehler.includes(waehler)) return { fehler: 'Deine Stimme liegt schon vor.' };

    if (s.codes) {
      // Bremse gegen Durchprobieren: nach zu vielen Fehlversuchen ist Schluss,
      // bis der Wahlleiter freigibt. Ohne das wäre ein Code in Stunden geraten.
      if (s.fehlversuche >= MAX_FEHLVERSUCHE) {
        return { fehler: 'Zu viele Fehlversuche. Bitte beim Wahlleiter melden.' };
      }
      const cH = await hashen(s.salt, codeNormal(code));
      const treffer = s.codes.find((c) => c.h === cH && !c.benutzt);
      if (!treffer) {
        s.fehlversuche = (s.fehlversuche || 0) + 1;
        await this.state.storage.put('sitzung', s);
        const uebrig = MAX_FEHLVERSUCHE - s.fehlversuche;
        return {
          fehler:
            'Zugangscode ungültig oder schon benutzt.' +
            (uebrig <= 3 && uebrig > 0 ? ` Noch ${uebrig} Versuche.` : ''),
        };
      }
      treffer.benutzt = true;
    }

    let gewaehlt = null;
    if (s.optionen) {
      const i = parseInt(antwort, 10);
      if (!(i >= 0 && i < s.optionen.length)) return { fehler: 'Bitte eine Antwort auswählen.' };
      s.zaehler[i]++;
      // Nur die Probe-Abstimmung gibt die Antwort heraus, damit der Worker sie
      // in die anonyme Strichliste legen kann. Bei echten Abstimmungen verlässt
      // sie dieses Objekt nie.
      if (s.demo) gewaehlt = s.optionen[i].text;
    } else {
      const wert = normalisieren(antwort || '');
      if (!wert) return { fehler: 'Bitte eine Antwort eingeben.' };
      const h = await hashen(s.salt, wert);
      if (s.ersterHash === null) s.ersterHash = h;
      else if (h !== s.ersterHash) s.einig = false;
      s.letzterWert = wert; // nur im Arbeitsspeicher dieser Anfrage relevant
    }

    s.abgegeben++;
    // Kennung merken, damit niemand zweimal abstimmt. Sortiert, damit die
    // Reihenfolge nicht verrät, wer wann dran war.
    s.waehler.push(waehler);
    s.waehler.sort();

    // Wahlquittung: ein Beleg, der nichts über den Inhalt der Stimme verrät.
    // Am Ende steht er in der öffentlichen Liste, so kann jeder nachsehen, dass
    // seine Stimme gezählt wurde. Auch sie wird sortiert abgelegt.
    const quittung = lesbarerCode(6);
    s.quittungen.push(quittung);
    s.quittungen.sort();

    if (s.abgegeben >= s.ziel) {
      s.ergebnis = this.auswerten(s);
      s.fertig = true;
      s.ersterHash = null;
      s.salt = zufall(16);
    }
    delete s.letzterWert;

    await this.state.storage.put('sitzung', s);
    return { ok: true, quittung, fertig: s.fertig, gewaehlt };
  }

  auswerten(s) {
    if (!s.optionen) {
      // Freitext: nur Einstimmigkeit. Der Klartext wird erst hier gespeichert,
      // und nur wenn er ohnehin Konsens ist, also allen bereits bekannt.
      return s.einig
        ? { erreicht: true, wert: s.letzterWert, modus: s.modus }
        : { erreicht: false, modus: s.modus };
    }

    const zaehlung = s.optionen.map((o, i) => ({
      text: o.text,
      zaehlt: o.zaehlt,
      stimmen: s.zaehler[i],
    }));
    const gueltige = zaehlung.filter((z) => z.zaehlt);
    const summe = gueltige.reduce((a, z) => a + z.stimmen, 0);
    const max = Math.max(0, ...gueltige.map((z) => z.stimmen));
    const spitze = gueltige.filter((z) => z.stimmen === max && max > 0);

    let erreicht = false;
    if (spitze.length === 1 && summe > 0) {
      if (s.modus === 'einstimmig') erreicht = max === summe;
      else if (s.modus === 'einfach') erreicht = max * 2 > summe;
      else if (s.modus === 'zweidrittel') erreicht = max * 3 >= summe * 2;
    }

    return {
      erreicht,
      wert: erreicht ? spitze[0].text : null,
      modus: s.modus,
      // Auszählung nur bei Mehrheitsentscheiden zeigen: dort gehört sie ins
      // Protokoll. Bei Einstimmigkeit wäre sie unnötige Preisgabe.
      zaehlung: s.modus === 'einstimmig' ? null : zaehlung,
      gueltige: summe,
      gleichstand: spitze.length > 1,
    };
  }

  /** Fehlversuchsbremse lösen. Nur mit Admin-Token, jederzeit möglich. */
  async entsperren(s, { admin }) {
    if (!s || admin !== s.admin) return { fehler: 'nicht erlaubt' };
    s.fehlversuche = 0;
    await this.state.storage.put('sitzung', s);
    return { ok: true };
  }
}

